import React, { useState } from "react";
import "./Login.css";

function Login({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState("");
  const [isRegister, setIsRegister] = useState(false); // 🔥 toggle state

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    try {
      const url = isRegister
        ? "http://localhost:5000/api/auth/register"
        : "http://localhost:5000/api/auth/login";

      const res = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ email, password })
      });

      const data = await res.json();

      if (data.success) {
        if (isRegister) {
          setMessage("Registered successfully! Now login.");
          setIsRegister(false); // switch back to login
        } else {
          onLogin(); // move to next page
        }
      } else {
        setMessage(data.message || "Something went wrong");
      }

    } catch (err) {
      console.error("ERROR:", err);
      setMessage("Server connection failed");
    }
  };

  return (
    <div className="main-container">

      {/* LEFT PANEL */}
      <div className="left-panel">
        <h1>Expense Intelligence</h1>
        <p>Smart Financial Management for Modern Users</p>
      </div>

      {/* RIGHT PANEL */}
      <div className="right-panel">
        <div className="form-box">
          
          <h2>{isRegister ? "Register" : "Login"}</h2>

          <form onSubmit={handleSubmit}>
            <input
              type="email"
              placeholder="Email Address"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />

            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />

            <button type="submit">
              {isRegister ? "Register" : "Continue"}
            </button>
          </form>

          {/* 🔥 TOGGLE BUTTON */}
          <p className="toggle-text">
            {isRegister ? "Already have an account?" : "Don’t have an account?"}{" "}
            <span
              onClick={() => {
                setIsRegister(!isRegister);
                setMessage("");
              }}
              style={{ cursor: "pointer", color: "#2a5298", fontWeight: "600" }}
            >
              {isRegister ? "Login" : "Register"}
            </span>
          </p>

          {message && (
  <p
    id="message"
    style={{
      color: message.toLowerCase().includes("success")
        ? "#28a745"   // green
        : "red"       // error
    }}
  >
    {message}
  </p>
)}
        </div>
      </div>

    </div>
  );
}

export default Login;
